#property strict
#property indicator_chart_window
#property indicator_buffers 1
input int Period = 14;
double Result[];
int OnInit() {
    SetIndexBuffer(0, Result);
    ArraySetAsSeries(Result, true);
    return(INIT_SUCCEEDED);
}
int OnCalculate(const int rates_total, const int prev_calculated,
    const datetime &time[], const double &open[], const double &high[],
    const double &low[], const double &close[], const long &tick_volume[],
    const long &volume[], const int &spread[]) {
    if(Period < 1 || rates_total < Period) return(0);
    ArraySetAsSeries(close, true);
    for(int shift = rates_total - Period; shift >= 0; shift--) {
        double mean = 0.0;
        for(int j = 0; j < Period; j++) mean += close[shift + j];
        mean /= Period;
        Result[shift] = mean > 0.0 ? close[shift] / mean - 1.0 : EMPTY_VALUE;
    }
    return(rates_total);
}

